def compute(vars):
    costs_millions = vars["v1"]
    notes_billions = vars["v2"]
    notes_millions = notes_billions * 1000
    if notes_millions == 0:
        return None
    percentage = costs_millions / notes_millions * 100
    return {
        "value": percentage,
        "trace": {
            "costs_millions": costs_millions,
            "notes_billions": notes_billions,
            "notes_millions": notes_millions,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
